from typing import List
import zipfile


def files_list_from_zipfile(zip_path: str) -> list[str]:
    """List all files inside a zip archive.

    Args:
        zip_path (str): The path to the zip file.

    Returns:
        list[str]: A list of file paths within the zip archive.
    """
    try:
        with zipfile.ZipFile(zip_path, 'r') as zip_file:
            return [file.filename for file in zip_file.infolist() if not file.is_dir()]
    except zipfile.BadZipFile:
        raise ValueError(f"The provided path {zip_path} does not point to a valid zip file.")
    except FileNotFoundError:
        raise ValueError(f"The file at path {zip_path} was not found.")


if __name__ == "__main__":
    # Example usage
    try:
        print(files_list_from_zipfile("example.zip"))
    except ValueError as e:
        print(e)

