import subprocess
from typing import List


def addignored() -> str:
    """Returns a comma-separated list of filenames that are ignored by Git, sorted alphabetically."""
    try:
        # Execute the git command to get ignored files
        result = subprocess.run(
            ["git", "ls-files", "-i", "--exclude-standard"],
            stdout=subprocess.PIPE,
            stderr=subprocess.PIPE,
            check=True,
        )
        ignored_files: List[str] = result.stdout.decode("utf-8").splitlines()

        # Sort the filenames alphabetically
        ignored_files.sort()

        # Join the filenames into a single string separated by commas
        return ",".join(ignored_files)

    except subprocess.CalledProcessError as e:
        raise RuntimeError(f"An error occurred while executing the git command: {e.stderr.decode('utf-8')}")

    except Exception as e:
        raise RuntimeError(f"An unexpected error occurred: {str(e)}")


if __name__ == "__main__":
    try:
        ignored_files_str = addignored()
        print(ignored_files_str)
    except RuntimeError as e:
        print(f"Runtime Error: {e}")

