from datetime import timedelta

def parse_frequency(frequency: str) -> timedelta:
    """Parses a frequency string into a datetime.timedelta object.

    Args:
        frequency (str): A string representing a time interval, e.g., '1 day', '2 hours', '3 minutes', '4 seconds'.
                         Special cases include 'None' and 'always'.

    Returns:
        timedelta: A datetime.timedelta object representing the parsed frequency.
                   Returns None for special cases 'None' and 'always'.

    Raises:
        ValueError: If the input string cannot be parsed into a valid timedelta.
    """
    if frequency.lower() == 'none':
        return None
    elif frequency.lower() == 'always':
        return None

    try:
        parts = frequency.split()
        if len(parts) != 2:
            raise ValueError("Invalid frequency format")

        amount = int(parts[0])
        unit = parts[1].lower()

        if unit.endswith('s'):
            unit = unit[:-1]

        if unit == 'day':
            return timedelta(days=amount)
        elif unit == 'hour':
            return timedelta(hours=amount)
        elif unit == 'minute':
            return timedelta(minutes=amount)
        elif unit == 'second':
            return timedelta(seconds=amount)
        else:
            raise ValueError("Unsupported time unit")
    except (ValueError, IndexError) as e:
        raise ValueError(f"Failed to parse frequency '{frequency}': {e}")

