import re
from typing import Union

def get_pattern(pattern: Union[str, re.Pattern], strip: bool = True) -> re.Pattern:
    """Converts a string or regex pattern object into a regex pattern object, optionally stripping leading and trailing spaces.

    Args:
        pattern (Union[str, re.Pattern]): The input pattern which can be either a string or a regex pattern object.
        strip (bool): Whether to strip leading and trailing spaces from the input string before converting it to a regex pattern object. Defaults to True.

    Returns:
        re.Pattern: The regex pattern object.
    """
    if isinstance(pattern, str):
        if strip:
            pattern = pattern.strip()
        return re.compile(pattern)
    elif isinstance(pattern, re.Pattern):
        return pattern
    else:
        raise ValueError("Input must be a string or a regex pattern object.")
